const E = { low: 0, medium: 1, high: 2 }, D = { easy: 1, medium: 2, hard: 3 };

function score(f, c) {
  let s = 0;
  if (c.environment !== "any" && !f.env.includes(c.environment)) return -1; // never send someone to the wrong kind of place
  if (f.groups && c.company === "solo") return -1;
  if (c.minutes < f.min[0] || c.minutes > f.min[1]) s -= 2; else s += 2;
  if (f.act === c.activity) s += 3;
  const e = E[c.energy]; if (e >= f.energy[0] && e <= f.energy[1]) s += 2; else s -= 3;
  s -= Math.abs(f.diff - D[c.difficulty]);
  if (f.groups && f.groups.includes(c.company)) s += 2;
  return s;
}
const hash = str => { let h = 2166136261; for (const ch of str) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); } return h >>> 0; };

// Best-first list of quests that fit the person's situation. Constraints (place, group) are hard rules; the
// on-device AI may only RE-ORDER this list, never add to it, so a match can never be unsafe or off-topic.
export function rankCandidates(context, { exclude = [], seed = "", k = 14 } = {}) {
  const scored = FALLBACKS.map(f => ({ f, s: score(f, context) })).filter(x => x.s >= 0);
  const pool = scored.length ? scored : FALLBACKS.filter(f => context.environment === "any" || f.env.includes(context.environment)).map(f => ({ f, s: 0 }));
  const fresh = pool.filter(x => !exclude.includes(x.f.id)), use = fresh.length ? fresh : pool;
  return use.map(x => ({ ...x, j: hash(seed + x.f.id + JSON.stringify(context)) % 1000 }))
    .sort((a, b) => (b.s - a.s) || (a.j - b.j)).slice(0, k).map(x => x.f);
}
export const pickFallback = (context, seed = "", exclude = []) => rankCandidates(context, { seed, exclude, k: 1 })[0];

export function fallbackDraft(context, seed, exclude, chosen = null) {
  const f = chosen || pickFallback(context, seed, exclude);
  const steps = [...f.steps];
  if (context.company !== "solo") steps.push(context.company === "family" ? "Share what each of you noticed before you head back." : "Compare what each of you noticed before you head back.");
  return { templateId: f.id, title: f.title, intro: f.intro, steps, reflectionPrompt: f.reflection };
}
